/**
 * Represents an entry of a song listened to on Spotify.
 */
interface SpotifyListenedSongEntry {
    /**
     * Timestamp indicating when the track stopped playing in UTC (Coordinated Universal Time).
     * Format: YYYY-MM-DDTHH:MM:SSZ
     * @example "2021-06-21T17:18:03Z"
     */
    ts?: string;

    /**
     * The platform used when streaming the track (e.g., Android OS, Google Chromecast).
     * @example "Linux [x86-64 0]"
     */
    platform?: string;

    /**
     * Number of milliseconds the track was played.
     * @example 5282
     */
    ms_played?: number;

    /**
     * Country code of the country where the stream was played.
     * @example "DE"
     */
    conn_country?: string;

    /**
     * IP address logged when streaming the track.
     * @example "24.134.224.161"
     */
    ip_addr?: string;

    /**
     * Name of the track.
     * @example "À nos souvenirs"
     */
    master_metadata_track_name?: string;

    /**
     * Name of the artist, band, or podcast.
     * @example "Trois Cafés Gourmands"
     */
    master_metadata_album_artist_name?: string;

    /**
     * Name of the album of the track.
     * @example "Un air de rien"
     */
    master_metadata_album_album_name?: string;

    /**
     * A Spotify URI, uniquely identifying the track.
     * Format: "spotify:track:<base-62 string>"
     * @example "spotify:track:3LgrzjwX7RVTtAX9Ai12Qm"
     */
    spotify_track_uri?: string;

    /**
     * Name of the episode of the podcast, if applicable.
     */
    episode_name?: string;

    /**
     * Name of the show of the podcast, if applicable.
     */
    episode_show_name?: string;

    /**
     * A Spotify URI, uniquely identifying the podcast episode.
     * Format: "spotify:episode:<base-62 string>"
     */
    spotify_episode_uri?: string;

    /**
     * Title of the audiobook, if applicable.
     */
    audiobook_title?: string;

    /**
     * A Spotify URI, uniquely identifying the audiobook.
     */
    audiobook_uri?: string;

    /**
     * A Spotify URI, uniquely identifying the audiobook chapter.
     */
    audiobook_chapter_uri?: string;

    /**
     * Title of the audiobook chapter, if applicable.
     */
    audiobook_chapter_title?: string;

    /**
     * Value indicating why the track started playing (e.g., "trackdone").
     * @example "fwdbtn"
     */
    reason_start?: string;

    /**
     * Value indicating why the track ended (e.g., "endplay").
     * @example "backbtn"
     */
    reason_end?: string;

    /**
     * Indicates whether shuffle mode was enabled when playing the track.
     * @example true
     */
    shuffle?: boolean;

    /**
     * Indicates whether the user skipped to the next song.
     * @example false
     */
    skipped?: boolean;

    /**
     * Indicates whether the track was played in offline mode.
     * @example false
     */
    offline?: boolean;

    /**
     * Timestamp of when offline mode was used, if applicable.
     */
    offline_timestamp?: string;

    /**
     * Indicates whether the track was played during a private session.
     * @example false
     */
    incognito_mode?: boolean;
}

interface Input {
    fileAsset: AssetDto;
}

interface Output {
    activities: ASActivity[];
}

function transformSpotifyTrack(entry: SpotifyListenedSongEntry, activityStableKeyService: ActivityStableKeyService): ASObject {
    return {
        "@type": "Audio",
        "@secondaryTypes": ["MusicRecording", "SpotifyTrack"],
        stableKeys: [
            activityStableKeyService.createASObjectStableKey("Audio", {
                type: "MusicRecording",
                name: entry.master_metadata_track_name,
                artist: entry.master_metadata_album_artist_name
            }),
            activityStableKeyService.createASObjectStableKey("Audio", {
                identifier: entry.spotify_track_uri
            }),
        ],
        identifier: entry.spotify_track_uri,
        name: entry.master_metadata_track_name,
        byArtist: entry.master_metadata_album_artist_name,
        inAlbum: entry.master_metadata_album_album_name
    }
}

function transformSpotifyEpisode(entry: SpotifyListenedSongEntry, activityStableKeyService: ActivityStableKeyService): ASObject {
    return {
        "@type": "Audio",
        "@secondaryTypes": ["PodcastEpisode", "SpotifyEpisode"],
        stableKeys: [
            activityStableKeyService.createASObjectStableKey("Audio", {
                type: "PodcastEpisode",
                name: entry.episode_name,
                showName: entry.episode_show_name
            }),
            activityStableKeyService.createASObjectStableKey("Audio", {
                identifier: entry.spotify_episode_uri
            }),
        ],
        identifier: entry.spotify_episode_uri,
        name: entry.episode_name,
        showName: entry.episode_show_name
    }
}

function summarize(audioType: "track" | "episode", entry: SpotifyListenedSongEntry) {
    const durationMinutes = Duration.fromMillis(entry.ms_played ?? 0).as("minutes");
    const typeName = audioType === "track" ? "song" : "podcast episode";
    const name = audioType === "track" ? entry.master_metadata_track_name : entry.episode_name;

    return `Listened to ${typeName} "${name}" for ${durationMinutes.toFixed(1)} minute${durationMinutes > 1 ? "s" : ""}`;
}

function transformEntry(entry: SpotifyListenedSongEntry, { logger, ownerActor, generatorExtensionObject, activityStableKeyService }: PipelineModuleExecutionContext<Input>): ASActivity {
    const startTime = DateTime.fromISO(entry.ts);

    if (!startTime) {
        throw new Error("Can't parse startTime in song entry" + JSON.stringify(entry));
    }

    const durationMillis = entry.ms_played ?? 0;
    const duration = Duration.fromMillis(durationMillis);
    const endTime = startTime.plus(duration);
    const audioType = Boolean(entry.master_metadata_track_name) ? "track" : Boolean(entry.episode_name) ? "episode" : "audiobook";

    if (audioType === "audiobook") {
        logger.log("Found audiobook entry!");
        logger.log(JSON.stringify(entry));

        throw new Error("Can't process audiobook entries yet, found one on" + entry.ts);
    }

    return {
        "@type": "Listen",
        "@secondaryTypes": ["SpotifyListenActivity"],
        generator: generatorExtensionObject,
        stableKeys: [
            activityStableKeyService.createActivityStableKey("Listen", {
                start: startTime,
                end: endTime
            }, { dateTimePrecision: "minute" })
        ],
        actor: ownerActor,
        summary: summarize(audioType, entry),
        object: audioType === "track" ? transformSpotifyTrack(entry, activityStableKeyService) : transformSpotifyEpisode(entry, activityStableKeyService),
        startTime,
        endTime,
        ...Object.fromEntries([
            ["platform", entry.platform],
            ["ipAddress", entry.ip_addr],
            ["reasonStart", entry.reason_start],
            ["reasonEnd", entry.reason_end],
            ["shuffle", entry.shuffle],
            ["skipped", entry.skipped],
            ["offline", entry.offline],
            ["offlineTimestamp", entry.offline_timestamp],
            ["incogniteMode", entry.incognito_mode]
        ].filter(([k, v]) => typeof v !== "undefined" && v !== null))
    }
}

async function executeModule(context: PipelineModuleExecutionContext<Input>): Promise<Output> {
    const { inputData, assetService, em } = context;
    const content = await assetService.getAssetString(em, inputData.fileAsset);
    const entries = JSON.parse(content) as SpotifyListenedSongEntry[];

    return {
        activities: entries.map((e) => transformEntry(e, context))
    };
}
